class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        cnt = Counter(nums)
        ans = []
        for num in nums:
            if cnt[num] > 0:
                ans.append(num)
                cnt[num] -= 1

        res = []
        i = 0
        while len(res) < len(ans):
            if len(ans) == 0 or ans[-1] % 2 == 1:
                if i < len(ans):
                    res.append(ans[i])
                    i += 1
            else:
                if i < len(ans) and ans[i] % 2 == 0:
                    res.append(ans[i])
                    i += 1

        return max(res)

