class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        counter = Counter(nums)
        ans = float('-inf')
        for num in sorted(counter.keys(), reverse=True):
            while counter[num] > 0:
                if len(nums) < k + counter[num]:
                    counter[num] -= 1
                    continue
                if nums[-(k + counter[num]):] == [num]*k:
                    ans = max(ans, num)
                break
        return ans if ans != float('-inf') else -1
